function aabbOverlap(ax: int, ay: int, aw: int, ah: int, bx: int, by: int, bw: int, bh: int): int {
    let aLeft: int = ax;
    let aRight: int = ax + aw;
    let aTop: int = ay;
    let aBottom: int = ay + ah;

    let bLeft: int = bx;
    let bRight: int = bx + bw;
    let bTop: int = by;
    let bBottom: int = by + bh;

    if (aRight <= bLeft) {
        return 0;
