function aabb_collision(a: table, b: table): int {
    let a_left: int = a.x;
    let a_bottom: int = a.y;
    let a_right: int = a.x + a.w;
    let a_top: int = a.y + a.h;

    let b_left: int = b.x;
    let b_bottom: int = b.y;
    let b_right: int = b.x + b.w;
    let b_top: int = b.y + b.h;

    // Check for overlap (touching edges are not overlap)
    if (a_left >= b_right) { return 0; }
    if (a_right <= b_left) { return 0; }
    if (a_bottom >= b_top) { return 0; }
    if (a_top <= b_bottom) { return 0; }

    return 1;
}

