  for (let t: int = 0; t < ticks; t = t + 1) {
    positions.p0 = positions.p0 + velocities.p0;
    positions.p1 = positions.p1 + velocities.p1;
    positions.p2 = positions.p2 + velocities.p2;
    positions.p3 = positions.p3 + velocities.p3;
