function checkRows(board: table): string {
    for (let i: int = 0; i < 3; i = i + 1) {
        let start: int = i * 3;
        if (board[start] !== "" && board[start] === board[start + 1] && board[start + 1] === board[start + 2]) {
            return board[start];
        }
    }
    return "";
}

function checkCols(board: table): string {
    for (let i: int = 0; i < 3; i = i + 1) {
        if (board[i] !== "" && board[i] === board[i + 3] && board[i + 3] === board[i + 6]) {
            return board[i];
        }
    }
    return "";
}

function checkDiags(board: table): string {
    if (board[0] !== "" && board[0] === board[4] && board[4] === board[8]) {
        return board[0];
    }
    if (board[2] !== "" && board[2] === board[4] && board[4] === board[6]) {
        return board[2];
    }
    return "";
}

function checkWinner(board: table): string {
    let result: string = checkRows(board);
    if (result === "") {
        result = checkCols(board);
    }
    if (result === "") {
        result = checkDiags(board);
    }
    return result;
}

