function countNeighbors(grid: table, x: int, y: int): int {
    let count: int = 0;
    let cells: table = grid.cells;

    for (let dy: int = -1; dy <= 1; dy = dy + 1) {
        for (let dx: int = -1; dx <= 1; dx = dx + 1) {
            if (dx === 0 && dy === 0) {
                continue;
            }
            let nx: int = x + dx;
            let ny: int = y + dy;
            if (nx >= 0 && nx < 3 && ny >= 0 && ny < 3) {
                let row: table = cells[ny];
                let cell: table = row[nx];
                if (cell.value === 1) {
                    count = count + 1;
                }
            }
        }
    }
    return count;
}

